#!/usr/bin/env node
/**
 * intake-manual.mjs — take the clips the founder generated by hand in Flow and
 * hand them to the tested collect/upload path.
 *
 * Generation is manual because Google blocks it, not because nobody wrote the
 * code — see the header of make-paste-pack.mjs for the four things that were
 * tried and why each is closed. Everything after generation stays automatic.
 *
 * PAIRING IS BY ORDER, exactly as collect-clips.mjs does it, because Flow names
 * its output after prompt content and tells us nothing reliable. The paste pack
 * is numbered top to bottom and the downloads are sorted by mtime, so working
 * the pack in order is what makes this correct. `--dry` prints the mapping and
 * changes nothing, and is the right way to check before committing to it.
 *
 * A wrong pairing is worse than a missing clip: a beat with no footage merely
 * shortens a shot, a beat with the WRONG footage is a lie on the page.
 */
import { readFileSync, writeFileSync, existsSync, mkdirSync, readdirSync, copyFileSync, statSync } from "fs";
import { join, dirname } from "path";
import { fileURLToPath } from "url";
import { execFileSync } from "child_process";
import os from "os";

const HERE = dirname(fileURLToPath(import.meta.url));
const DL = join(HERE, "downloads");
const QUEUE = join(HERE, "veo_queue.json");
const SRC = process.env.VEO_INTAKE_DIR || join(os.homedir(), "Downloads");
const DRY = process.argv.includes("--dry");
const SINCE_H = Number(process.env.VEO_INTAKE_HOURS || 24);

mkdirSync(DL, { recursive: true });
const cutoff = Date.now() - SINCE_H * 3600 * 1000;

if (!existsSync(SRC)) { console.log(`[intake] no source dir ${SRC}`); process.exit(0); }

// Pull in anything Flow-shaped the founder downloaded in the window.
const fresh = readdirSync(SRC)
  .filter((f) => /\.(mp4|zip)$/i.test(f))
  .map((f) => ({ f, p: join(SRC, f), t: statSync(join(SRC, f)).mtimeMs }))
  .filter((x) => x.t >= cutoff)
  .sort((a, b) => a.t - b.t);

if (!fresh.length) {
  console.log(`[intake] nothing newer than ${SINCE_H}h in ${SRC}`);
  process.exit(0);
}
console.log(`[intake] ${fresh.length} candidate file(s) in ${SRC} (last ${SINCE_H}h)`);

for (const x of fresh) {
  const dest = join(DL, x.f);
  if (existsSync(dest) && statSync(dest).size === statSync(x.p).size) continue;
  if (!DRY) copyFileSync(x.p, dest);
  console.log(`[intake] ${DRY ? "would take" : "took"} ${x.f}`);
}

// Flow's batch zips carry inner names that break `unzip`; python's zipfile does
// not care. Same handling as collect-clips.mjs, done here so the mp4 count is
// known BEFORE we decide how many queue rows to mark.
const zipEntries = (zipPath) => {
  try {
    const out = execFileSync("python3", ["-c",
      `import zipfile,sys
print("\\n".join(n for n in zipfile.ZipFile(sys.argv[1]).namelist() if n.lower().endswith('.mp4')))`,
      zipPath], { encoding: "utf-8" });
    return out.split("\n").filter(Boolean);
  } catch { return []; }
};

if (!DRY) {
  for (const f of readdirSync(DL).filter((x) => x.toLowerCase().endsWith(".zip"))) {
    try {
      execFileSync("python3", ["-c",
        `import zipfile,sys,os
z=zipfile.ZipFile(sys.argv[1])
for i,n in enumerate(z.namelist()):
    if not n.lower().endswith('.mp4'): continue
    out=os.path.join(sys.argv[2], f'unzipped_{os.path.basename(sys.argv[1])}_{i}.mp4')
    if os.path.exists(out): continue
    with z.open(n) as s, open(out,'wb') as d: d.write(s.read())`, join(DL, f), DL]);
      console.log(`[intake] unpacked ${f}`);
    } catch (e) { console.log(`[intake] could not unpack ${f}: ${String(e).slice(0, 90)}`); }
  }
}

// The prospective clip list, in the order collect-clips.mjs will see it.
// A --dry run copies nothing, so it must PREDICT that list rather than read the
// downloads dir — otherwise the one check that exists to catch a mis-pairing
// before it happens silently reports "nothing to pair". (Caught by test, 09-21.)
let mp4s;
if (DRY) {
  const seen = new Set();
  const items = [];
  for (const f of readdirSync(DL).filter((x) => x.endsWith(".mp4"))) {
    seen.add(f); items.push({ f, t: statSync(join(DL, f)).mtimeMs });
  }
  for (const x of fresh) {
    if (/\.mp4$/i.test(x.f)) {
      if (!seen.has(x.f)) items.push({ f: x.f, t: x.t });
    } else {
      zipEntries(x.p).forEach((n, i) =>
        items.push({ f: `${x.f} -> ${n.split("/").pop()}`, t: x.t + i }));
    }
  }
  mp4s = items.sort((a, b) => a.t - b.t).map((x) => x.f);
} else {
  mp4s = readdirSync(DL).filter((f) => f.endsWith(".mp4"))
    .map((f) => ({ f, t: statSync(join(DL, f)).mtimeMs }))
    .sort((a, b) => a.t - b.t).map((x) => x.f);
}

const q = JSON.parse(readFileSync(QUEUE, "utf-8"));
const pending = q.filter((r) => r.status === "pending");
const n = Math.min(mp4s.length, pending.length);

if (!n) { console.log("[intake] no mp4s and/or no pending rows — nothing to pair"); process.exit(0); }
if (mp4s.length > pending.length) {
  console.log(`[intake] ${mp4s.length} clips but only ${pending.length} pending rows — pairing the first ${n}, leaving the rest`);
}

console.log("\n[intake] pairing (order matters — check this):");
for (let i = 0; i < n; i++) console.log(`   ${String(i + 1).padStart(2)}  ${mp4s[i]}  ->  ${pending[i].clip}`);

if (DRY) { console.log("\n[intake] --dry: nothing written"); process.exit(0); }

// collect-clips.mjs renames by matching `generated` rows in queue order, so we
// mark exactly the rows we just paired and let the tested path do the renaming.
for (let i = 0; i < n; i++) pending[i].status = "generated";
writeFileSync(QUEUE, JSON.stringify(q, null, 2));
console.log(`\n[intake] marked ${n} row(s) generated — collect-clips.mjs will name them`);
